import { exportJWK, generateKeyPair, SignJWT } from 'jose';
import * as nock from 'nock';

const AUTH0_ORIGIN = 'https://AUTH0_DOMAIN_REDACTED';
export const ISSUER = 'https://AUTH0_DOMAIN_REDACTED/';
export const AUDIENCE = 'AUTH0_AUDIENCE_REDACTED';

export interface TokenClaims {
  sub: string;
  iss?: string;
  aud?: string;
  /** seconds from epoch; pass a past value for an expired token */
  exp?: number;
}

export interface TestAuth {
  /** sign a token the app will accept (unless claims are deliberately wrong) */
  signToken(claims: TokenClaims): Promise<string>;
  /** profile served by the mocked /userinfo, keyed by sub */
  userinfoProfiles: Map<string, { email: string; name?: string }>;
  /** how many times /userinfo was actually hit */
  userinfoCalls(): number;
  cleanup(): void;
}

// Local RS256 keypair + nocked JWKS/userinfo. Exercises the REAL jwks-rsa
// verification path (kid lookup, cache, issuer/audience checks) with zero
// live Auth0 traffic (ADR-010).
export async function setupTestAuth(): Promise<TestAuth> {
  const { publicKey, privateKey } = await generateKeyPair('RS256', {
    extractable: true,
  });
  const jwk = {
    ...(await exportJWK(publicKey)),
