  userinfoProfiles: Map<string, { email: string; name?: string }>;
  /** how many times /userinfo was actually hit */
  userinfoCalls(): number;
  cleanup(): void;
}

// Local RS256 keypair + nocked JWKS/userinfo. Exercises the REAL jwks-rsa
// verification path (kid lookup, cache, issuer/audience checks) with zero
// live Auth0 traffic (ADR-010).
export async function setupTestAuth(): Promise<TestAuth> {
  const { publicKey, privateKey } = await generateKeyPair('RS256', {
    extractable: true,
  });
  const jwk = {
    ...(await exportJWK(publicKey)),
    kid: 'test-key',
    alg: 'RS256',
    use: 'sig',
  };

  const userinfoProfiles = new Map<string, { email: string; name?: string }>();
  let userinfoHits = 0;

  nock(AUTH0_ORIGIN)
    .persist()
    .get('/.well-known/jwks.json')
    .reply(200, { keys: [jwk] });

  nock(AUTH0_ORIGIN)
    .persist()
    .get('/userinfo')
    .reply(function () {
      userinfoHits += 1;
      const auth = this.req.headers.authorization ?? '';
      const token = String(auth).replace(/^Bearer /, '');
      const payload = JSON.parse(
        Buffer.from(token.split('.')[1], 'base64url').toString(),
      ) as { sub: string };
      const profile = userinfoProfiles.get(payload.sub);
      if (!profile) return [401, { error: 'unknown test sub' }];
      return [200, { sub: payload.sub, ...profile }];
    });

  nock.disableNetConnect();
  nock.enableNetConnect(/127\.0\.0\.1|localhost/);

  return {
    async signToken(claims: TokenClaims): Promise<string> {
      const now = Math.floor(Date.now() / 1000);
      return new SignJWT({})
        .setProtectedHeader({ alg: 'RS256', kid: 'test-key' })
        .setIssuer(claims.iss ?? ISSUER)
        .setAudience(claims.aud ?? AUDIENCE)
        .setSubject(claims.sub)
        .setIssuedAt(now)
        .setExpirationTime(claims.exp ?? now + 600)
        .sign(privateKey);
    },
    userinfoProfiles,
    userinfoCalls: () => userinfoHits,
    cleanup: () => {
      nock.cleanAll();
      nock.enableNetConnect();
    },
  };
}

