import { INestApplication } from '@nestjs/common';
import request from 'supertest';

import { setupTestAuth, TestAuth } from './utils/test-auth';
import {
  disconnectTestPrisma,
  getTestPrisma,
  truncateAll,
} from './utils/test-db';
import { createTestApp } from './utils/test-app';

describe('Collections (e2e)', () => {
  let app: INestApplication;
  let auth: TestAuth;
  let tokenA: string;
  let tokenB: string;
  let userAId: string;
  let userBId: string;

  const server = (): ReturnType<INestApplication['getHttpServer']> =>
    app.getHttpServer();

  beforeAll(async () => {
    auth = setupTestAuth();
    app = await createTestApp();
    tokenA = auth.signToken({ sub: 'auth0|user-a' });
    tokenB = auth.signToken({ sub: 'auth0|user-b' });
  });

  beforeEach(async () => {
    await truncateAll();
    const prisma = getTestPrisma();
    const a = await prisma.user.create({
      data: { sub: 'auth0|user-a', email: 'EMAIL_REDACTED' },
    });
    const b = await prisma.user.create({
      data: { sub: 'auth0|user-b', email: 'EMAIL_REDACTED' },
    });
    userAId = a.id;
    userBId = b.id;
  });

  afterAll(async () => {
    await app.close();
    await disconnectTestPrisma();
    auth.cleanup();
  });

  const createCollection = async (
    token: string,
    name: string,
  ): Promise<{ id: string }> => {
    const res = await request(server())
      .post('/api/collections')
      .set('Authorization', `Bearer ${token}`)
      .send({ name })
      .expect(201);
    return res.body as { id: string };
  };

  describe('CRUD happy paths', () => {
    it('POST -> 201 with isOwner, GET one -> 200, list -> paginated', async () => {
      const { id } = await createCollection(tokenA, 'Engineering');

      const one = await request(server())
        .get(`/api/collections/${id}`)
        .set('Authorization', `Bearer ${tokenA}`)
        .expect(200);
      expect(one.body as Record<string, unknown>).toMatchObject({
        id,
        name: 'Engineering',
        ownerId: userAId,
        isOwner: true,
      });

      const list = await request(server())
        .get('/api/collections')
        .set('Authorization', `Bearer ${tokenA}`)
        .expect(200);
      const body = list.body as {
        data: unknown[];
        meta: Record<string, number>;
      };
