    ['seed-col-other-work', 'Work Notes', other.id],
    ['seed-col-other-travel', 'Travel Plans', other.id],
  ] as const) {
    const col = await prisma.collection.upsert({
      where: { id },
      update: {},
      create: { id, name, ownerId },
